public static List<BenchResult> runAllAndCollectResults(
            DataSet ds,
            boolean enableIndexCache,
            List<Integer> mGrid,
            List<Integer> efConstructionGrid,
            List<Float> neighborOverflowGrid,
            List<Boolean> addHierarchyGrid,
            List<Boolean> refineFinalGraphGrid,
            List<? extends Set<FeatureId>> featureSets,
            List<Function<DataSet, CompressorParameters>> buildCompressors,
            List<Function<DataSet, CompressorParameters>> compressionGrid,
            Map<Integer, List<Double>> topKGrid,
            List<Boolean> usePruningGrid) throws IOException {

        // Initialize index caching (if enabled)
        final OnDiskGraphIndexCache cache =
                enableIndexCache
                        ? OnDiskGraphIndexCache.initialize(Paths.get(indexCacheDir))
                        : OnDiskGraphIndexCache.disabled();

        List<BenchResult> results = new ArrayList<>();
        for (int m : mGrid) {
            for (int ef : efConstructionGrid) {
                for (float neighborOverflow : neighborOverflowGrid) {
                    for (boolean addHierarchy : addHierarchyGrid) {
                        for (boolean refineFinalGraph : refineFinalGraphGrid) {
                            for (Set<FeatureId> features : featureSets) {
                                for (Function<DataSet, CompressorParameters> buildCompressor : buildCompressors) {
                                    for (Function<DataSet, CompressorParameters> searchCompressor : compressionGrid) {
                                        Path testDirectory = Files.createTempDirectory("bench");
                                        try (var diagnostics = new BenchmarkDiagnostics(getDiagnosticLevel())) {
                                            // Capture initial state
                                            diagnostics.startMonitoring("testDirectory", testDirectory);
                                            diagnostics.startMonitoring("indexCache", Paths.get(indexCacheDir));
                                            diagnostics.capturePrePhaseSnapshot("Build");
                                            Map<Set<FeatureId>, ImmutableGraphIndex> indexes = new HashMap<>();
                                            Map<Set<FeatureId>, Long> indexFileSizes = new HashMap<>();

                                            var compressor = getCompressor(buildCompressor, ds);
                                            var searchCompressorObj = getCompressor(searchCompressor, ds);
                                            // Encode vectors for reranking if a compressor is provided
                                            CompressedVectors cvArg;
                                            if (features.contains(FeatureId.FUSED_PQ)) {
                                                cvArg = null;
                                                System.out.format("%s: configured to use FUSED PQ, skipping vector compression%n", ds.getName());
                                            } else {
                                                if (searchCompressorObj == null) {
                                                    cvArg = null;
                                                    System.out.format("%s: No search compressor configured, " +
                                                            "FULL PRECISION vectors will be used for search%n", ds.getName());
                                                } else {
                                                    cvArg = searchCompressorObj.encodeAll(ds.getBaseRavv());
                                                    if (cvArg == null) {
                                                        throw new IllegalStateException(String.format(
                                                                "Compressor '%s' was provided but failed to encode vectors for dataset '%s'. " +
                                                                        "Aborting to prevent false recall results.",
                                                                searchCompressorObj, ds.getName()));
                                                    }
                                                    System.out.format("%s: %s encoded %d vectors [%.2f MB] for search%n",
                                                            ds.getName(), searchCompressorObj, ds.getBaseVectors().size(),
                                                            (cvArg.ramBytesUsed() / 1024f / 1024f));
                                                }
                                            }
                                            // If cache is disabled, we use the (tmp) testDirectory as the output
                                            Path outputDir = cache.isEnabled() ? cache.cacheDir().toAbsolutePath() : testDirectory;

                                            List<Set<FeatureId>> missing = new ArrayList<>();
                                            // Map feature sets to their cache handles for the build phase
                                            Map<Set<FeatureId>, OnDiskGraphIndexCache.WriteHandle> handles = new HashMap<>();

                                            for (Set<FeatureId> fs : featureSets) {
                                                var key = cache.key(ds.getName(), fs, m, ef, neighborOverflow, 1.2f, addHierarchy, refineFinalGraph, compressor);
                                                var cached = cache.tryLoad(key);

                                                if (cached.isPresent()) {
                                                    System.out.printf("%s: Using cached graph index for %s%n", key.datasetName, fs);
                                                    indexes.put(fs, cached.get());
                                                    try { indexFileSizes.put(fs, Files.size(cache.resolve(key).finalPath)); } catch (IOException ignored) {}
                                                } else {
                                                    missing.add(fs);
                                                    if (cache.isEnabled()) {
                                                        var handle = cache.beginWrite(key, OnDiskGraphIndexCache.Overwrite.ALLOW);
                                                        // Log cache miss / build start
                                                        System.out.printf("%s: Building graph index (cached enabled) for %s%n",
                                                                key.datasetName, fs);
                                                        // Prepare the atomic write handle immediately
                                                        handles.put(fs, handle);
                                                    } else {
                                                        System.out.printf("%s: Building graph index (cache disabled) for %s%n", key.datasetName, fs);
                                                    }
                                                }
                                            }

                                            if (!missing.isEmpty()) {
                                                // At least one index needs to be built (b/c not in cache or cache is disabled)
                                                // We pass the handles map so buildOnDisk knows exactly where to write
                                                var result = buildOnDisk(missing, m, ef, neighborOverflow, addHierarchy, refineFinalGraph,
                                                        ds, outputDir, compressor, handles, null);
                                                indexes.putAll(result.indexes);
                                                indexFileSizes.putAll(result.fileSizes);
                                            }

                                            ImmutableGraphIndex index = indexes.get(features);

                                            // Capture post-build state
                                            diagnostics.capturePostPhaseSnapshot("Build");
                                            diagnostics.printDiskStatistics("Graph Index Build");
                                            var buildSnapshot = diagnostics.getLatestSystemSnapshot();

                                            try (ConfiguredSystem cs = new ConfiguredSystem(ds, index, cvArg, features)) {
                                                int queryRuns = 2;
                                                List<QueryBenchmark> benchmarks = List.of(
                                                        (diagnostic_level > 0 ?
                                                                ThroughputBenchmark.createDefault().withDiagnostics(getDiagnosticLevel()) :
                                                                ThroughputBenchmark.createDefault()),
                                                        LatencyBenchmark.createDefault(),
                                                        CountBenchmark.createDefault(),
                                                        AccuracyBenchmark.createDefault(),
                                                        CountBenchmark.createDefault()
                                                );
                                                QueryTester tester = new QueryTester(benchmarks, testDirectory, ds.getName());
                                                for (int topK : topKGrid.keySet()) {
                                                    for (boolean usePruning : usePruningGrid) {
                                                        for (double overquery : topKGrid.get(topK)) {
                                                            int rerankK = (int) (topK * overquery);
                                                            List<Metric> metricsList = tester.run(cs, topK, rerankK, usePruning, queryRuns);
                                                            Map<String, Object> params = new LinkedHashMap<>();
                                                            params.put("M", m);
                                                            params.put("efConstruction", ef);
                                                            params.put("neighborOverflow", neighborOverflow);
                                                            params.put("addHierarchy", addHierarchy);
                                                            params.put("refineFinalGraph", refineFinalGraph);
                                                            params.put("features", features.toString());
                                                            params.put("buildCompressor", buildCompressor.toString());
                                                            params.put("searchCompressor", searchCompressor.toString());
                                                            params.put("topK", topK);
                                                            params.put("overquery", overquery);
                                                            params.put("usePruning", usePruning);

                                                            // Collect all metrics including memory and disk usage
                                                            Map<String, Object> allMetrics = new HashMap<>();
                                                            for (Metric metric : metricsList) {
                                                                allMetrics.put(metric.getHeader(), metric.getValue());
                                                            }

                                                            // Add build time if available
                                                            if (indexBuildTimes.containsKey(ds.getName())) {
                                                                allMetrics.put("Index Build Time", indexBuildTimes.get(ds.getName()));
                                                            }

                                                            // Add memory metrics if available
                                                            if (buildSnapshot != null) {
                                                                allMetrics.put("Heap Memory Used (MB)", buildSnapshot.memoryStats.heapUsed / 1024.0 / 1024.0);
                                                                allMetrics.put("Heap Memory Max (MB)", buildSnapshot.memoryStats.heapMax / 1024.0 / 1024.0);
                                                                allMetrics.put("Off-Heap Direct (MB)", buildSnapshot.memoryStats.directBufferMemory / 1024.0 / 1024.0);
                                                                allMetrics.put("Off-Heap Mapped (MB)", buildSnapshot.memoryStats.mappedBufferMemory / 1024.0 / 1024.0);
                                                                allMetrics.put("Total Off-Heap (MB)", buildSnapshot.memoryStats.getTotalOffHeapMemory() / 1024.0 / 1024.0);
                                                            }

                                                            // Add per-feature-set index file size
                                                            Long fileSizeBytes = indexFileSizes.get(features);
                                                            if (fileSizeBytes != null) {
                                                                allMetrics.put("Disk Usage (MB)", fileSizeBytes / 1024.0 / 1024.0);
                                                            }

                                                            results.add(new BenchResult(ds.getName(), params, allMetrics));
                                                        }
                                                    }
                                                }
                                            } catch (Exception e) {
                                                throw new RuntimeException(e);
                                            }
                                        } finally {
                                            for (int n = 0; n < 1; n++) {
                                                try {
                                                    Files.deleteIfExists(testDirectory.resolve("graph" + n));
                                                } catch (IOException e) { /* ignore */ }
                                            }
                                            try {
                                                Files.deleteIfExists(testDirectory);
                                            } catch (IOException e) { /* ignore */ }

                                            if (enableIndexCache) {
                                                System.out.println("Preserving index cache directory: " + indexCacheDir);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        return results;
    }

static VectorizationProvider lookup(boolean testMode) {
    String forcedProvider = System.getProperty("jvector.vectorization_provider");
    if (forcedProvider != null) {
      switch (forcedProvider.toLowerCase(Locale.ROOT)) {
        case "default":
          return new DefaultVectorizationProvider();
        case "panama":
          try {
            return (VectorizationProvider) Class.forName("io.github.jbellis.jvector.vector.PanamaVectorizationProvider").getConstructor().newInstance();
          } catch (Throwable e) {
            throw new RuntimeException("Failed to load forced PanamaVectorizationProvider", e);
          }
        case "native":
          try {
            return (VectorizationProvider) Class.forName("io.github.jbellis.jvector.vector.NativeVectorizationProvider").getConstructor().newInstance();
          } catch (Throwable e) {
            throw new RuntimeException("Failed to load forced NativeVectorizationProvider", e);
          }
        default:
          throw new IllegalArgumentException("Unknown vectorization provider: " + forcedProvider);
      }
    }

    final int runtimeVersion = Runtime.version().feature();
    if (runtimeVersion >= 20) {
      // is locale sane (only buggy in Java 20)
      if (isAffectedByJDK8301190()) {
        LOG.warning(
            "Java runtime is using a buggy default locale; Java vector incubator API can't be enabled: "
                + Locale.getDefault());
        return new DefaultVectorizationProvider();
      }
      // is the incubator module present and readable (JVM providers may to exclude them or it is
      // build with jlink)
      if (!vectorModulePresentAndReadable()) {
        LOG.warning(
            "Java vector incubator module is not readable. For optimal vector performance, pass '--add-modules jdk.incubator.vector' to enable Vector API.");
        return new DefaultVectorizationProvider();
      }
      if (!testMode && isClientVM()) {
        LOG.warning("C2 compiler is disabled; Java vector incubator API can't be enabled");
        return new DefaultVectorizationProvider();
      }

      // check for jvector.experimental.enable_native_vectorization
      // this is an experimental feature subject to change
      if (Boolean.getBoolean("jvector.experimental.enable_native_vectorization")) {
        try {
          Class<?> clazz = Class.forName("io.github.jbellis.jvector.vector.NativeVectorizationProvider");
          Constructor<?> ctor = clazz.getConstructor();
          Object instance = ctor.newInstance();
          var provider = (VectorizationProvider) instance;
          try {
            var support = provider.getVectorUtilSupport();
            String isa = (String) support.getClass().getMethod("getActiveIsa").invoke(support);
            LOG.info("Native Vector API enabled. Using NativeVectorizationProvider.");
            String maxIsa = (String) support.getClass().getMethod("getMaxIsaEnv").invoke(support);
            LOG.info("Highway ISA tier: " + isa + ", Env variable JVECTOR_MAX_ISA: " + (maxIsa != null ? maxIsa : "(not set)"));
          } catch (Exception e) {
            LOG.info("Native Vector API enabled. Using NativeVectorizationProvider. (Unable to determine Highway ISA tier)");
          }
          return provider;
        } catch (UnsupportedOperationException uoe) {
          LOG.warning("Native vector API was not enabled. " + uoe.getMessage());
        } catch (ClassNotFoundException e) {
          LOG.warning("Java version does not support native vector API");
        } catch (InvocationTargetException e) {
          // unwrap, check for UnsupportedOperationException
          if (e.getCause() instanceof UnsupportedOperationException) {
            LOG.warning("Native vector API was not enabled. " + e.getCause().getMessage());
          } else {
            throw new AssertionError(e);
          }
        } catch (Throwable th) {
          throw new AssertionError(th);
        }
      }

      try {
        var provider = (VectorizationProvider) Class.forName("io.github.jbellis.jvector.vector.PanamaVectorizationProvider").getConstructor().newInstance();
        LOG.info("Java incubating Vector API enabled. Using PanamaVectorizationProvider.");
        return provider;
      } catch (UnsupportedOperationException uoe) {
        // not supported because preferred vector size too small or similar
        LOG.warning("Java vector API was not enabled. " + uoe.getMessage());
        return new DefaultVectorizationProvider();
      } catch (ClassNotFoundException e) {
        LOG.warning("Java version does not support vector API");
        return new DefaultVectorizationProvider();
      } catch (RuntimeException | Error e) {
        throw e;
      } catch (Throwable th) {
        throw new AssertionError(th);
      }
    } else {
      LOG.warning("You are running with Java 19 or earlier, which do not support the required incubating Vector API. Falling back to slower defaults.");
    }
    return new DefaultVectorizationProvider();
  }

@Setup(Level.Iteration)
    public void setup() throws Exception {
        try {
            resultPersisted = false;
            Thread.currentThread().setName("compactor-" + workerCounter.incrementAndGet());

            if (vectorizationProvider != null && !vectorizationProvider.isBlank()) {
                System.setProperty("jvector.vectorization_provider", vectorizationProvider);
            }
            resolvedVectorizationProvider = VectorizationProvider.getInstance().getClass().getSimpleName();

            if (sysStatsEnabled) {
                String sysStatsFileName = String.format("sysstats-%s.jsonl", jfrParamSuffix());
                try {
                    sysStatsCollector.start(SYSTEM_DIR, sysStatsFileName);
                } catch (Exception e) {
                    log.warn("Failed to start system stats collection", e);
                }
            }

            if (threadAllocTracking) {
                String threadAllocFileName = String.format("threadalloc-%s.jsonl", jfrParamSuffix());
                try {
                    threadAllocTracker.start(SYSTEM_DIR, threadAllocFileName);
                } catch (Exception e) {
                    log.warn("Failed to start thread allocation tracking", e);
                }
            }

            persistStarted();

            validateParams();

            int dimension;

            boolean needsBaseVectors = workloadMode != WorkloadMode.COMPACT;
            boolean needsRecallData = measureRecall && workloadMode != WorkloadMode.PARTITION;

            if (needsBaseVectors) {
                ds = DataSets.loadDataSet(datasetNames)
                        .orElseThrow(() -> new RuntimeException("Dataset not found: " + datasetNames))
                        .getDataSet();

                if (datasetPortion == 1.0) {
                    ravv = ds.getBaseRavv();
                    baseVectors = ds.getBaseVectors();
                } else {
                    int totalVectors = ds.getBaseRavv().size();
                    int portionedSize = (int) (totalVectors * datasetPortion);
                    if (portionedSize < Math.max(1, numPartitions)) {
                        throw new IllegalArgumentException(
                                "datasetPortion=" + datasetPortion + " yields " + portionedSize
                                        + " vectors, fewer than numPartitions=" + numPartitions);
                    }
                    baseVectors = ds.getBaseVectors().subList(0, portionedSize);
                    ravv = new ListRandomAccessVectorValues(baseVectors, ds.getDimension());
                }

                similarityFunction = ds.getSimilarityFunction();
                dimension = ds.getDimension();

                if (needsRecallData) {
                    queryVectors = ds.getQueryVectors();
                    groundTruth = ds.getGroundTruth();
                    log.info("Dataset {} loaded with recall data. Base vectors: {} (portion {}), Query vectors: {}, Dim: {}, Similarity: {}, Workload: {}, measureRecall: {}, Live nodes rate: {}",
                            datasetNames, ravv.size(), datasetPortion, queryVectors.size(), dimension, similarityFunction, workloadMode, measureRecall, liveNodesRate);
                } else {
                    queryVectors = null;
                    groundTruth = null;
                    log.info("Dataset {} loaded (base vectors only). Base vectors: {} (portion {}), Dim: {}, Similarity: {}, Workload: {}, measureRecall: {}",
                            datasetNames, ravv.size(), datasetPortion, dimension, similarityFunction, workloadMode, measureRecall);
                }
            } else {
                ravv = null;
                baseVectors = null;
                dimension = -1;

                if (needsRecallData) {
                    ds = DataSets.loadDataSet(datasetNames)
                            .orElseThrow(() -> new RuntimeException("Dataset not found: " + datasetNames))
                            .getDataSet();
                    queryVectors = ds.getQueryVectors();
                    groundTruth = ds.getGroundTruth();
                    similarityFunction = ds.getSimilarityFunction();
                    log.info("Dataset {} loaded for {} mode with recall data (base vectors skipped). Query vectors: {}, Similarity: {}, Live nodes rate: {}",
                            datasetNames, workloadMode, queryVectors.size(), similarityFunction, liveNodesRate);
                } else {
                    ds = null;
                    queryVectors = null;
                    groundTruth = null;

                    var datasetInfo = DataSets.loadDataSet(datasetNames);
                    similarityFunction = datasetInfo
                            .flatMap(DataSetInfo::similarityFunction)
                            .orElseGet(() -> {
                                log.warn("Could not determine similarity function for dataset '{}'; defaulting to COSINE", datasetNames);
                                return VectorSimilarityFunction.COSINE;
                            });

                    log.info("Skipping dataset load for {} mode. similarityFunction: {}, Live nodes rate: {}",
                            workloadMode, similarityFunction, liveNodesRate);
                }
            }

            // Resolve storagePaths + partitionsDir
            storagePaths = resolveStoragePaths();
            partitionsBaseDir = resolvePartitionsBaseDir(storagePaths);
            compactOutputPath = resolveCompactOutputPath(partitionsBaseDir);
            scratchOutputPath = resolveScratchOutputPath(partitionsBaseDir);

            if (workloadMode == WorkloadMode.COMPACT) {
                verifyPartitionsExist(partitionsBaseDir, numPartitions);
            }

            if (workloadMode == WorkloadMode.PARTITION || workloadMode == WorkloadMode.PARTITION_AND_COMPACT) {
                var partitionedData = DataSetPartitioner.partition(baseVectors, numPartitions, splitDistribution);
                vectorsPerSourceCount = partitionedData.sizes;
            } else {
                vectorsPerSourceCount = null;
            }

            if (workloadMode == WorkloadMode.PARTITION || workloadMode == WorkloadMode.PARTITION_AND_COMPACT) {
                if (jfrPartitioning) {
                    jfrPartitioningRecorder.start(JFR_DIR, "partitioning-" + jfrParamSuffix() + ".jfr", jfrObjectCount);
                }
                buildPartitions(ds, baseVectors);
                if (jfrPartitioningRecorder.isActive()) {
                    jfrPartitioningRecorder.stop();
                }
            }

        } catch (Exception e) {
            persistError(e);
            throw e;
        }
    }

static void runOneGraph(OnDiskGraphIndexCache cache,
                            List<? extends Set<FeatureId>> featureSets,
                            int M,
                            int efConstruction,
                            float neighborOverflow,
                            boolean addHierarchy,
                            boolean refineFinalGraph,
                            Function<DataSet, CompressorParameters> buildCompressor,
                            List<Function<DataSet, CompressorParameters>> compressionGrid,
                            Map<Integer, List<Double>> topKGrid,
                            List<Boolean> usePruningGrid,
                            RunArtifacts artifacts,
                            DataSet ds,
                            Path workDirectory) throws IOException
    {
        // Prepare to collect index construction metrics for reporting....
        var constructionMetrics = new ConstructionMetrics();

        // Capture initial memory and disk state
        try (var diagnostics = new BenchmarkDiagnostics(getDiagnosticLevel())) {
            diagnostics.startMonitoring("testDirectory", workDirectory);
            diagnostics.startMonitoring("indexCache", Paths.get(indexCacheDir));
            diagnostics.capturePrePhaseSnapshot("Graph Build");
            System.out.printf("%s: Dataset similarity function is %s%n", ds.getName(), ds.getSimilarityFunction());

            // Resolve build compressor (and label quant type) so we can record compute time
            VectorCompressor<?> buildCompressorObj = null;
            String buildQuantType = null;

            if (buildCompressor != null) {
                var buildParams = buildCompressor.apply(ds);
                buildQuantType = quantTypeOf(buildParams); // "PQ", "BQ", or null
                buildCompressorObj = getCompressor(buildCompressor, ds, constructionMetrics, Phase.INDEX, buildQuantType);
            }

            // Used in logging
            String buildCompressorString =
                    (buildCompressorObj == null) ? "None" : String.valueOf(buildCompressorObj);

            Map<Set<FeatureId>, ImmutableGraphIndex> indexes = new HashMap<>();
            Map<Set<FeatureId>, Long> indexFileSizes = new HashMap<>();
            if (buildCompressorObj == null) {
                indexes = buildInMemory(featureSets, M, efConstruction, neighborOverflow, addHierarchy, refineFinalGraph, ds, workDirectory);
            } else {
                // If cache is disabled, we use the (tmp) workDirectory as the output
                Path outputDir = cache.isEnabled() ? cache.cacheDir().toAbsolutePath() : workDirectory;

                List<Set<FeatureId>> missing = new ArrayList<>();
                // Map feature sets to their cache handles for the build phase
                Map<Set<FeatureId>, OnDiskGraphIndexCache.WriteHandle> handles = new HashMap<>();

                for (Set<FeatureId> fs : featureSets) {
                    var key = cache.key(ds.getName(), fs, M, efConstruction, neighborOverflow, 1.2f, addHierarchy, refineFinalGraph, buildCompressorObj);
                    var cached = cache.tryLoad(key);

                    if (cached.isPresent()) {
                        System.out.printf("%s: Using cached graph index for %s%n", key.datasetName, fs);
                        indexes.put(fs, cached.get());
                        try { indexFileSizes.put(fs, Files.size(cache.resolve(key).finalPath)); } catch (IOException ignored) {}
                    } else {
                        missing.add(fs);
                        if (cache.isEnabled()) {
                            var handle = cache.beginWrite(key, OnDiskGraphIndexCache.Overwrite.ALLOW);
                            // Log cache miss / build start
                            System.out.printf("%s: Building graph index (cached enabled) for %s%n", key.datasetName, fs);
                            // Prepare the atomic write handle immediately
                            handles.put(fs, handle);
                        } else {
                            System.out.printf("%s: Building graph index (cache disabled) for %s%n", key.datasetName, fs);
                        }
                    }
                }

                if (!missing.isEmpty()) {
                    // At least one index needs to be built (b/c not in cache or cache is disabled)
                    // We pass the handles map so buildOnDisk knows exactly where to write
                    var result = buildOnDisk(missing, M, efConstruction, neighborOverflow, addHierarchy, refineFinalGraph,
                            ds, outputDir, buildCompressorObj, handles, constructionMetrics);
                    indexes.putAll(result.indexes);
                    indexFileSizes.putAll(result.fileSizes);
                }
            }

            // Capture post-build memory and disk state
            diagnostics.capturePostPhaseSnapshot("Graph Build");

            diagnostics.printDiskStatistics("Graph Index Build");
            System.out.printf("Index build time: %f seconds%n%n", Grid.getIndexBuildTimeSeconds(ds.getName()));
            constructionMetrics.indexBuildTimeS = Grid.getIndexBuildTimeSeconds(ds.getName());

            try {
                for (var cpSupplier : compressionGrid) {
                    indexes.forEach((features, index) -> {
                        constructionMetrics.indexFileSizeBytes = indexFileSizes.get(features);
                        final Set<FeatureId> featureSetForIndex = index instanceof OnDiskGraphIndex ? ((OnDiskGraphIndex) index).getFeatureSet() : Set.of();

                        CompressedVectors cv;
                        if (featureSetForIndex.contains(FeatureId.FUSED_PQ)) {
                            cv = null;
                            System.out.format("%s: configured to use FUSED PQ, skipping vector compression%n", ds.getName());
                        } else {
                            constructionMetrics.resetSearch(); // per (index, cpSupplier) config

                            var searchParams = cpSupplier.apply(ds);
                            String searchQuantType = quantTypeOf(searchParams); // "PQ", "BQ", or null
                            var compressor = getCompressor(cpSupplier, ds, constructionMetrics, Phase.SEARCH, searchQuantType);

                            if (compressor == null) {
                                cv = null;
                                System.out.format("%s: No search compressor configured, FULL PRECISION vectors will be used for search%n", ds.getName());
                            } else {
                                long start = System.nanoTime();
                                cv = constructionMetrics.search(searchQuantType)
                                        .timeEncode(() -> compressor.encodeAll(ds.getBaseRavv()));
                                double encodingTimeS = (System.nanoTime() - start) / 1_000_000_000.0;
                                if (cv == null) {
                                    throw new IllegalStateException(String.format(
                                            "Compressor '%s' was provided but failed to encode vectors for dataset '%s'. " +
                                                    "Aborting to prevent false recall results.", compressor, ds.getName()));
                                }
                                System.out.format("%s: %s encoded %d vectors [%.2f MB] in %.2fs%n", ds.getName(), compressor, ds.getBaseVectors().size(), (cv.ramBytesUsed() / 1024f / 1024f), encodingTimeS);
                            }
                        }

                        try (var cs = new ConfiguredSystem(ds, index, cv, featureSetForIndex)) {
                            testConfiguration(cs, topKGrid, usePruningGrid, M, efConstruction, neighborOverflow, addHierarchy, refineFinalGraph, featureSetForIndex,
                                    buildCompressorString, artifacts, constructionMetrics, workDirectory);
                        } catch (Exception e) {
                            throw new RuntimeException(e);
                        }
                    });
                }
                for (var index : indexes.values()) {
                    index.close();
                }

                // Log final diagnostics summary
                if (diagnostic_level > 0) {
                    diagnostics.logSummary();
                }
            } finally {
                // Clean up the tmp files for this run
                for (int n = 0; n < featureSets.size(); n++) {
                    Path p = workDirectory.resolve("graph" + n);
                    try {
                        Files.deleteIfExists(p);
                    } catch (IOException e) {
                        // Log and move on; don't let a delete-fail mask a real exception
                        System.err.println("Cleanup Failed: Could not delete " + p.getFileName() + " -> " + e.getMessage());
                    }
                }
            }
        }
    }

@Override
    public List<Metric> runBenchmark(
            ConfiguredSystem cs,
            int topK,
            int rerankK,
            boolean usePruning,
            int queryRuns) {

        if (!(computeAvgQps || computeMedianQps || computeMaxQps)) {
            throw new RuntimeException("At least one metric must be displayed");
        }
        try (BenchmarkDiagnostics diagnostics = new BenchmarkDiagnostics(diagnosticLevel)) {

            int totalQueries = cs.getDataSet().getQueryVectors().size();
            int dim = cs.getDataSet().getDimension();

            // Warmup Phase with diagnostics
            double[] warmupQps = new double[numWarmupRuns];
            for (int warmupRun = 0; warmupRun < numWarmupRuns; warmupRun++) {
                String warmupPhase = "Warmup-" + warmupRun;

                warmupQps[warmupRun] = diagnostics.monitorPhaseWithQueryTiming(warmupPhase, (recorder) -> {
                    IntStream.range(0, totalQueries)
                            .parallel()
                            .forEach(k -> {
                                long queryStart = System.nanoTime();

                                // Generate a random vector
                                VectorFloat<?> randQ = vts.createFloatVector(dim);
                                for (int j = 0; j < dim; j++) {
                                    randQ.set(j, ThreadLocalRandom.current().nextFloat());
                                }
                                VectorUtil.l2normalize(randQ);
                                SearchResult sr = QueryExecutor.executeQuery(
                                        cs, topK, rerankK, usePruning, randQ);
                                SINK += sr.getVisitedCount();

                                long queryEnd = System.nanoTime();
                                recorder.recordTime(queryEnd - queryStart);
                            });

                    return totalQueries / 1.0; // Return QPS placeholder
                });

                diagnostics.console("Warmup Run " + warmupRun + ": " + warmupQps[warmupRun] + " QPS\n");
            }

            // Analyze warmup effectiveness
            if (numWarmupRuns > 1) {
                double warmupVariance = StatUtils.variance(warmupQps);
                double warmupMean = StatUtils.mean(warmupQps);
                double warmupCV = Math.sqrt(warmupVariance) / warmupMean * 100;
                diagnostics.console("Warmup Analysis: Mean=" + warmupMean + " QPS, CV=" + warmupCV);

                if (warmupCV > 15.0) {
                    diagnostics.console(" ⚠️  High warmup variance - consider more warmup runs\n");
                } else {
                    diagnostics.console(" ✓ Warmup appears stable\n");
                }
            }

            double[] qpsSamples = new double[numTestRuns];
            for (int testRun = 0; testRun < numTestRuns; testRun++) {
                String testPhase = "Test-" + testRun;

                // Clear Eden and let GC complete with diagnostics monitoring
                diagnostics.monitorPhase("GC-" + testRun, () -> {
                    System.gc();
                    System.runFinalization();
                    try {
                        Thread.sleep(500);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                    }
                    return null;
                });

                // Test Phase with detailed monitoring
                qpsSamples[testRun] = diagnostics.monitorPhaseWithQueryTiming(testPhase, (recorder) -> {
                    LongAdder visitedAdder = new LongAdder();
                    long startTime = System.nanoTime();

                    IntStream.range(0, totalQueries)
                            .parallel()
                            .forEach(i -> {
                                long queryStart = System.nanoTime();

                                SearchResult sr = QueryExecutor.executeQuery(
                                        cs, topK, rerankK, usePruning, i);
                                // "Use" the result to prevent optimization
                                visitedAdder.add(sr.getVisitedCount());

                                long queryEnd = System.nanoTime();
                                recorder.recordTime(queryEnd - queryStart);
                            });

                    double elapsedSec = (System.nanoTime() - startTime) / 1e9;
                    return totalQueries / elapsedSec;
                });

                diagnostics.console("Test Run " + testRun + ": " + qpsSamples[testRun] + " QPS\n");
            }

            // Performance variance analysis
            Arrays.sort(qpsSamples);
            double medianQps = qpsSamples[numTestRuns / 2];
            double avgQps = StatUtils.mean(qpsSamples);
            double stdDevQps = Math.sqrt(StatUtils.variance(qpsSamples));
            double maxQps = StatUtils.max(qpsSamples);
            double minQps = StatUtils.min(qpsSamples);
            double coefficientOfVariation = (stdDevQps / avgQps) * 100;

            diagnostics.console("QPS Variance Analysis: CV=" + coefficientOfVariation + ", Range=[" + minQps + " - " + maxQps + "]\n");

            if (coefficientOfVariation > 10.0) {
                diagnostics.console("⚠️  High performance variance detected (CV > 10%%)%n");
            }

            // Compare test runs for performance regression detection
            if (numTestRuns > 1) {
                diagnostics.comparePhases("Test-0", "Test-" + (numTestRuns - 1));
            }

            // Generate final diagnostics summary and recommendations
            diagnostics.logSummary();
            diagnostics.provideRecommendations();

            var list = new ArrayList<Metric>();
            if (computeAvgQps) {
                list.add(Metric.of("search.throughput.avg_qps",
                        "Avg QPS\n (of " + numTestRuns + ")",
                        formatAvgQps,
                        avgQps));

                list.add(Metric.of("search.throughput.stddev_qps",
                        "± Std Dev",
                        formatAvgQps,
                        stdDevQps));

                list.add(Metric.of("search.throughput.cv_pct",
                        "CV %",
                        ".1f",
                        coefficientOfVariation));
            }
            if (computeMedianQps) {
                list.add(Metric.of("search.throughput.median_qps",
                        "Median QPS\n (of " + numTestRuns + ")",
                        formatMedianQps,
                        medianQps));
            }
            if (computeMaxQps) {
                list.add(Metric.of("search.throughput.max_qps",
                        "Max QPS\n (of " + numTestRuns + ")",
                        formatMaxQps,
                        maxQps));

                list.add(Metric.of("search.throughput.min_qps",
                        "Min QPS\n (of " + numTestRuns + ")",
                        formatMaxQps,
                        minQps));
            }
            return list;
        }
        catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
